+  psql_dm() { "$TDF_SOCIAL_PG_BIN/psql" -h 127.0.0.1 -p "$TDF_SOCIAL_PORT" -X -v ON_ERROR_STOP=1 -v dm_benchmark="${TDF_SOCIAL_DM_BENCHMARK:-0}" -U postgres -d social_dm "$@"; }
